# Improved Vision OCR with column awareness and confidence
cat > /tmp/vision_ocr.swift << 'SWIFT'
import Foundation
import Vision
import AppKit

struct Box {
    let text: String
    let conf: Float
    let x: CGFloat
    let y: CGFloat  // top of box in Vision coords (origin bottom-left)
    let w: CGFloat
    let h: CGFloat
    var midX: CGFloat { x + w/2 }
    var midY: CGFloat { y + h/2 }
}

guard CommandLine.arguments.count > 1 else {
    fputs("Usage: vision_ocr [--tsv] <image>\n", stderr)
    exit(1)
}

var tsv = false
var path = ""
for arg in CommandLine.arguments.dropFirst() {
    if arg == "--tsv" { tsv = true } else { path = arg }
}

guard let img = NSImage(contentsOfFile: path),
      let tiff = img.tiffRepresentation,
      let rep = NSBitmapImageRep(data: tiff),
      let cgImage = rep.cgImage else {
    fputs("Failed to load image: \(path)\n", stderr)
    exit(1)
}

let request = VNRecognizeTextRequest()
request.recognitionLevel = .accurate
request.usesLanguageCorrection = true
request.recognitionLanguages = ["en-US"]

let handler = VNImageRequestHandler(cgImage: cgImage, options: [:])
try handler.perform([request])

guard let observations = request.results, !observations.isEmpty else { exit(0) }

var boxes: [Box] = []
for obs in observations {
    guard let c = obs.topCandidates(1).first else { continue }
    let b = obs.boundingBox
    boxes.append(Box(text: c.string, conf: c.confidence, x: b.minX, y: b.minY, w: b.width, h: b.height))
}

// Detect two-column layout: significant content on both left and right halves
let leftCount = boxes.filter { $0.midX < 0.48 }.count
let rightCount = boxes.filter { $0.midX > 0.52 }.count
let twoColumn = leftCount >= 8 && rightCount >= 8 && Double(min(leftCount, rightCount)) / Double(max(leftCount, rightCount)) > 0.25

func emit(_ items: [Box]) {
    // Cluster into lines by Y (Vision: higher Y = higher on page)
    let sorted = items.sorted { a, b in
        if abs(a.midY - b.midY) > 0.012 { return a.midY > b.midY }
        return a.x < b.x
    }
    var lines: [[Box]] = []
    for box in sorted {
        if let last = lines.last, let ref = last.first, abs(ref.midY - box.midY) <= 0.012 {
            lines[lines.count - 1].append(box)
        } else {
            lines.append([box])
        }
    }
    for var line in lines {
        line.sort { $0.x < $1.x }
        if tsv {
            for b in line {
                print("\(String(format: "%.3f", b.conf))\t\(b.text)")
            }
        } else {
            print(line.map { $0.text }.joined(separator: " "))
        }
    }
}

if twoColumn {
    let left = boxes.filter { $0.midX < 0.5 }
    let right = boxes.filter { $0.midX >= 0.5 }
    emit(left)
    print("\n---COLUMN_BREAK---\n")
    emit(right)
} else {
    emit(boxes)
}
