cat > /tmp/vision_ocr.swift << 'SWIFT'
import Foundation
import Vision
import AppKit

struct Box {
    let text: String
    let conf: Float
    let x: CGFloat
    let y: CGFloat
    let w: CGFloat
    let h: CGFloat
    var midX: CGFloat { x + w/2 }
    var midY: CGFloat { y + h/2 }
}

guard CommandLine.arguments.count >= 2 else {
    fputs("Usage: vision_ocr [--columns] [--force-columns] <image>\n", stderr)
    exit(1)
}

var mode = "auto" // auto | single | columns
var path = ""
for arg in CommandLine.arguments.dropFirst() {
    if arg == "--columns" || arg == "--force-columns" { mode = "columns" }
    else if arg == "--single" { mode = "single" }
    else { path = arg }
}

guard let img = NSImage(contentsOfFile: path),
      let tiff = img.tiffRepresentation,
      let rep = NSBitmapImageRep(data: tiff),
      let cgImage = rep.cgImage else {
    fputs("Failed to load image: \(path)\n", stderr)
    exit(1)
}

let request = VNRecognizeTextRequest()
request.recognitionLevel = .accurate
request.usesLanguageCorrection = true
request.recognitionLanguages = ["en-US"]

let handler = VNImageRequestHandler(cgImage: cgImage, options: [:])
try handler.perform([request])

guard let observations = request.results, !observations.isEmpty else { exit(0) }

var boxes: [Box] = []
var confSum: Float = 0
for obs in observations {
    guard let c = obs.topCandidates(1).first else { continue }
    let b = obs.boundingBox
    boxes.append(Box(text: c.string, conf: c.confidence, x: b.minX, y: b.minY, w: b.width, h: b.height))
    confSum += c.confidence
}
let avgConf = confSum / Float(boxes.count)

// Detect true dual-page / two-column: clear vertical gutter with little text
func hasGutter(_ items: [Box]) -> Bool {
    let gutter = items.filter { $0.midX >= 0.46 && $0.midX <= 0.54 }
    let left = items.filter { $0.midX < 0.45 }
    let right = items.filter { $0.midX > 0.55 }
    // Need substantial content both sides and sparse gutter
    guard left.count >= 15, right.count >= 15 else { return false }
    let gutterRatio = Double(gutter.count) / Double(items.count)
    return gutterRatio < 0.08
}

func emit(_ items: [Box]) -> [String] {
    let sorted = items.sorted { a, b in
        if abs(a.midY - b.midY) > 0.008 { return a.midY > b.midY }
        return a.x < b.x
    }
    var lines: [[Box]] = []
    for box in sorted {
        if let last = lines.last, let ref = last.first, abs(ref.midY - box.midY) <= 0.008 {
            lines[lines.count - 1].append(box)
        } else {
            lines.append([box])
        }
    }
    var out: [String] = []
    for var line in lines {
        line.sort { $0.x < $1.x }
        out.append(line.map { $0.text }.joined(separator: " "))
    }
    return out
}

let useColumns = (mode == "columns") || (mode == "auto" && hasGutter(boxes))

fputs(String(format: "<!-- ocr avg_conf=%.3f boxes=%d columns=%@ -->\n", avgConf, boxes.count, useColumns ? "yes" : "no"), stderr)

if useColumns {
    let left = boxes.filter { $0.midX < 0.5 }
    let right = boxes.filter { $0.midX >= 0.5 }
    for line in emit(left) { print(line) }
    print("\n---COLUMN_BREAK---\n")
    for line in emit(right) { print(line) }
} else {
    for line in emit(boxes) { print(line) }
}
